import React, { useState, useEffect } from 'react';
import { getReports, createReport, deleteReport } from '../services/api';
import './Pages.css';

export default function Reports() {
  const [reports, setReports] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    reportName: '',
    reportType: '',
    description: '',
    startDate: '',
    endDate: ''
  });

  useEffect(() => {
    fetchReports();
  }, []);

  const fetchReports = async () => {
    try {
      const res = await getReports();
      setReports(res.data);
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createReport(form);
      setForm({
        reportName: '',
        reportType: '',
        description: '',
        startDate: '',
        endDate: ''
      });
      setShowForm(false);
      fetchReports();
    } catch (err) {
      console.error('Error:', err);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Estás seguro?')) {
      try {
        await deleteReport(id);
        fetchReports();
      } catch (err) {
        console.error('Error:', err);
      }
    }
  };

  return (
    <div className="page">
      <h2>📊 Reportes</h2>

      <button onClick={() => setShowForm(!showForm)} className="btn-primary">
        {showForm ? 'Cancelar' : '+ Generar Reporte'}
      </button>

      {showForm && (
        <form onSubmit={handleSubmit} className="form-container">
          <input
            type="text"
            placeholder="Nombre del Reporte"
            value={form.reportName}
            onChange={(e) => setForm({ ...form, reportName: e.target.value })}
            required
          />
          <select
            value={form.reportType}
            onChange={(e) => setForm({ ...form, reportType: e.target.value })}
            required
          >
            <option value="">Tipo</option>
            <option value="appointments">Citas</option>
            <option value="payments">Pagos</option>
            <option value="patients">Pacientes</option>
          </select>
          <input
            type="date"
            value={form.startDate}
            onChange={(e) => setForm({ ...form, startDate: e.target.value })}
            required
          />
          <input
            type="date"
            value={form.endDate}
            onChange={(e) => setForm({ ...form, endDate: e.target.value })}
            required
          />
          <textarea
            placeholder="Descripción"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <button type="submit" className="btn-success">Generar</button>
        </form>
      )}

      <div className="cards-container">
        {reports.map((r) => (
          <div key={r.id} className="card-report">
            <h3>{r.reportName}</h3>
            <p>Tipo: {r.reportType}</p>
            <p>Período: {new Date(r.startDate).toLocaleDateString()} - {new Date(r.endDate).toLocaleDateString()}</p>
            <p>Estado: {r.status}</p>
            <button className="btn-danger" onClick={() => handleDelete(r.id)}>
              Eliminar
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
